// endregion

// region Scrolling
.smooth-scroll {
  transform: translateZ(0) !important;
}

.scrollbar-stable {
  scrollbar-gutter: stable;
}

.ve-overflow-auto {
  overflow: auto auto;
}

.ve-overflow-visible {
  overflow: visible visible !important;
}

.ve-overflow-y-auto {
  overflow-y: auto;
}

.ve-overflow-y-scroll {
