}

.ve-overflow-x-scroll {
  overflow-x: scroll;
}

.ve-overflow-x-hidden {
  overflow-x: hidden;
}

.ve-overflow-hidden {
  overflow: hidden;
}

.ve-overflow-ellipsis {
  @include vars.mix-overflow-dots;
}

.ve-overflow-overlay {
  overflow: auto;
