// region Columns
.columns-2 {
  column-count: 2;
  break-inside: avoid-column;
  column-gap: 1.75rem;

  > * {
    break-inside: avoid-column;
  }

  @media screen and (width <= #{vars.$width-screen-sm}) {
    column-count: 1;
  }
}

.columns-3 {
  column-count: 3;
